import convnet as cn, copy

def mk_x():
    return [[[ [0.1, 0.4, -0.2], [0.3, -0.5, 0.7], [0.9, 0.2, -0.1] ]],
            [[ [-0.3, 0.6, 0.2], [0.8, -0.4, 0.1], [0.5, 0.7, -0.6] ]]]

def mk_conv(): return cn.Conv2D([[[[0.2]]]], [0.01])
def mk_bn(): return cn.BatchNorm2D([1.2], [-0.3])
def mk_drop(): return cn.Dropout(0.25, seed=7)
def mk_flat(): return cn.Flatten()
def mk_lin(): return cn.Linear([[0.3, -0.2, 0.1, 0.4],[-0.1, 0.2, -0.3, 0.05]], [0.0, 0.0])
dy_lin = [[0.4, -0.7],[0.2, 0.5]]
labels = [0, 1]

# 3. check_norm_gradients with both pools
for pool in (cn.AvgPool2D(2, stride=1), cn.MaxPool2D(2, stride=1)):
    a = cn.check_norm_gradients(mk_conv(), mk_bn(), mk_drop(), pool, mk_flat(), mk_lin(), mk_x(), dy_lin)
    b = cn.check_norm_gradients(mk_conv(), mk_bn(), mk_drop(), pool, mk_flat(), mk_lin(), mk_x(), dy_lin)
    print("norm", type(pool).__name__, a, "repeat equal:", a == b)
    assert a[0]

try:
    cn.check_norm_gradients(mk_conv(), mk_bn(), mk_drop(), object(), mk_flat(), mk_lin(), mk_x(), dy_lin)
    raise AssertionError("no TypeError")
except TypeError as e:
    print("norm pool TypeError ok:", e)

# 4. check_train_gradients with both pools
def mk_loss(): return cn.SoftmaxCrossEntropy()
for pool in (cn.AvgPool2D(2, stride=1), cn.MaxPool2D(2, stride=1)):
    a = cn.check_train_gradients(mk_conv(), mk_bn(), mk_drop(), pool, mk_flat(), mk_lin(), mk_loss(), mk_x(), labels)
    b = cn.check_train_gradients(mk_conv(), mk_bn(), mk_drop(), pool, mk_flat(), mk_lin(), mk_loss(), mk_x(), labels)
    print("train", type(pool).__name__, a, "repeat equal:", a == b)
    assert a[0]

try:
    cn.check_train_gradients(mk_conv(), mk_bn(), mk_drop(), object(), mk_flat(), mk_lin(), mk_loss(), mk_x(), labels)
    raise AssertionError("no TypeError")
except TypeError as e:
    print("train pool TypeError ok:", e)

# MaxPool2D tie still raises in norm/train chains; AvgPool2D same input fine
x_tie = [[[[1.0, 1.0],[0.0, 0.5]]], [[[0.2, 0.9],[0.4, 0.1]]]]
def mk_id(): return cn.Conv2D([[[[1.0]]]], [0.0])
def mk_lin1(): return cn.Linear([[0.5]], [0.0])
for fn, extra in ((cn.check_norm_gradients, (mk_x(),)), ):
    pass
try:
    cn.check_norm_gradients(mk_id(), mk_bn(), mk_drop(), cn.MaxPool2D(2), cn.Flatten(), mk_lin1(), x_tie, [[0.3],[0.2]])
    raise AssertionError("no ValueError tie (norm)")
except ValueError as e:
    print("norm MaxPool tie ValueError ok:", e)
r = cn.check_norm_gradients(mk_id(), mk_bn(), mk_drop(), cn.AvgPool2D(2), cn.Flatten(), mk_lin1(), x_tie, [[0.3],[0.2]])
print("norm AvgPool tied input ok:", r); assert r[0]

try:
    cn.check_train_gradients(mk_id(), mk_bn(), mk_drop(), cn.MaxPool2D(2), cn.Flatten(), mk_lin1(), mk_loss(), x_tie, [0,0])
    raise AssertionError("no ValueError tie (train)")
except ValueError as e:
    print("train MaxPool tie ValueError ok:", e)
r = cn.check_train_gradients(mk_id(), mk_bn(), mk_drop(), cn.AvgPool2D(2), cn.Flatten(), mk_lin1(), mk_loss(), x_tie, [0,0])
print("train AvgPool tied input ok:", r); assert r[0]

# state restoration: dropout _s, bn running stats, loss cache unchanged
bn, dr, ls, pool = mk_bn(), mk_drop(), mk_loss(), cn.AvgPool2D(2, stride=1)
snap = [copy.deepcopy(o.__dict__) for o in (bn, dr, ls, pool)]
cn.check_train_gradients(mk_conv(), bn, dr, pool, mk_flat(), mk_lin(), ls, mk_x(), labels)
for o, s in zip((bn, dr, ls, pool), snap):
    assert o.__dict__ == s, (o, s)
print("bn/dropout/loss/pool state restored ok")
